package net.officefloor.hq.app.claim;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.Set;
import net.officefloor.hq.app.setting.OpenToViewer;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}")
public class ClaimController {

    /**
     * A claim as the screen shows it; the amount always has two decimals, and so does the due fixed
     * when it was settled (null while its due is live). Who opened it is null while DRAFT. Stated
     * when bound by its person's last statement, to the due it had then (null when it had none). A
     * correction has the number of the claim it corrects (null for any other claim). Its status log
     * is oldest first. Locked by the user whose open editor holds it (null when none). A late entry
     * when added while its period was soft-closed.
     */
    public record ClaimView(Long id, Long personId, String amount, LocalDate date, String note, ClaimStatus status,
            String number, String settledDue, String openedBy, boolean stated, String statedDue, String corrects,
            LocalDate dueBy, List<LogLineView> log, LocalDate deferredUntil,
            int proofs, String splitFrom, String lockedBy, boolean lateEntry) {
        public static ClaimView of(Claim claim) {
            return new ClaimView(claim.getId(), claim.getPersonId(), claim.getAmount().toPlainString(),
                    claim.getDate(), claim.getNote(), claim.getStatus(), claim.getNumber(),
                    claim.getSettledDue() == null ? null : claim.getSettledDue().setScale(2).toPlainString(),
                    claim.getOpenedBy(), claim.isStated(),
                    claim.getStatedDue() == null ? null : claim.getStatedDue().setScale(2).toPlainString(),
                    claim.getCorrects(), claim.getDueBy(), claim.getLog().stream().map(LogLineView::of).toList(),
                    claim.getDeferredUntil(), claim.getProofs(), claim.getSplitFrom(),
                    claim.getLockedBy(), claim.isLateEntry());
        }
    }

    /** A line of a claim's status log; its due has two decimals (null when it had none). */
    public record LogLineView(ClaimStatus status, String by, LocalDate date, String due) {
        static LogLineView of(ClaimLogEntry entry) {
            return new LogLineView(entry.getStatus(), entry.getBy(), entry.getDate(),
                    entry.getDue() == null ? null : entry.getDue().setScale(2).toPlainString());
        }
    }

    /**
     * A claim's amount (up to two decimals; negative for a correction), date (blank: the sheet's today),
     * note and, for a correction, the number of the claim it corrects.
     */
    public record ClaimRequest(
            @NotNull @Pattern(regexp = "-?\\d{1,12}(\\.\\d{1,2})?") String amount,
            LocalDate date,
            @Size(max = 500) String note,
            @Size(max = 220) @Pattern(regexp = "\\S+") String corrects) {

        BigDecimal amountValue() {
            return new BigDecimal(amount).setScale(2);
        }

        String correctsValue() {
            return corrects == null || corrects.isEmpty() ? null : corrects;
        }

        String noteValue() {
            return note == null ? "" : note.strip();
        }
    }

    /** Why a steward rejects a PENDING claim. */
    public record RejectRequest(@NotBlank @Size(max = 200) @Pattern(regexp = "\\S+( \\S+)*") String reason) {}

    /** The date an OPEN claim is deferred until: after the sheet's today. */
    public record DeferRequest(@NotNull LocalDate until) {}

    /** The new date of an OPEN or PENDING claim a steward re-dates. */
    public record RedateRequest(@NotNull LocalDate date) {}

    /** The person on the sheet a claim is moved to. */
    public record ReassignRequest(@NotNull Long personId) {}

    /** The amount split off an OPEN claim: more than 0.00 and less than its amount. */
    public record SplitRequest(@NotNull @Pattern(regexp = "\\d{1,12}(\\.\\d{1,2})?") String amount) {

        BigDecimal amountValue() {
            return new BigDecimal(amount).setScale(2);
        }
    }

    /** A split claim as it now is, and the new claim split off it. */
    public record SplitView(ClaimView original, ClaimView split) {}

    /** The claims selected for a bulk change, by id. */
    public record BulkRequest(@NotNull @Size(max = 1000) Set<@NotNull Long> ids) {}

    /** How many of the selected claims a bulk open opened, and how many it refused. */
    public record BulkOpenView(int opened, int refused) {}

    /** How many of the selected claims a bulk settle settled (or sent to PENDING), and how many it refused. */
    public record BulkSettleView(int settled, int refused) {}

    /** Pasted lines of name,amount,date,note, one claim each. */
    public record PasteRequest(@NotNull @Size(max = 200000) String text) {}

    /** The claims a paste added, in the order of their lines. */
    public record PasteView(int added, List<ClaimView> claims) {}

    private final ClaimService service;
    private final ClaimBulkService bulk;
    private final ClaimPasteService paste;

    public ClaimController(ClaimService service, ClaimBulkService bulk, ClaimPasteService paste) {
        this.service = service;
        this.bulk = bulk;
        this.paste = paste;
    }

    @GetMapping("/claims")
    public List<ClaimView> list(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return service.list(sheetId).stream().map(ClaimView::of).toList();
    }

    @PostMapping("/people/{personId}/claims")
    public ClaimView add(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable Long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid ClaimRequest request) {
        return ClaimView.of(service.add(sheetId, user, personId, request.amountValue(), request.date(), request.noteValue(),
                request.correctsValue()));
    }

    @PostMapping("/claims/paste")
    public PasteView paste(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid PasteRequest request) {
        List<ClaimView> added = paste.paste(sheetId, user, request.text()).stream().map(ClaimView::of).toList();
        return new PasteView(added.size(), added);
    }

    @PutMapping("/claims/{id}")
    public ClaimView edit(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable Long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid ClaimRequest request) {
        return ClaimView.of(service.edit(sheetId, user, id, request.amountValue(), request.date(), request.noteValue(),
                request.correctsValue()));
    }

    @PostMapping("/claims/{id}/edit")
    public ClaimView lock(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable Long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return ClaimView.of(service.lock(sheetId, user, id));
    }

    @PostMapping("/claims/{id}/cancel")
    public ClaimView unlock(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable Long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return ClaimView.of(service.unlock(sheetId, user, id));
    }

    @PostMapping("/claims/{id}/open")
    public ClaimView open(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable Long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return ClaimView.of(service.changeStatus(sheetId, user, id, ClaimStatus.OPEN));
    }

    @OpenToViewer
    @PostMapping("/claims/open")
    public BulkOpenView bulkOpen(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid BulkRequest request) {
        ClaimBulkService.Result result = bulk.open(sheetId, user, request.ids());
        return new BulkOpenView(result.done(), result.refused());
    }

    @OpenToViewer
    @PostMapping("/claims/settle")
    public BulkSettleView bulkSettle(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid BulkRequest request) {
        ClaimBulkService.Result result = bulk.settle(sheetId, user, request.ids());
        return new BulkSettleView(result.done(), result.refused());
    }

    @PostMapping("/claims/{id}/settle")
    public ClaimView settle(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable Long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return ClaimView.of(service.changeStatus(sheetId, user, id, ClaimStatus.SETTLED));
    }

    @PostMapping("/claims/{id}/void")
    public ClaimView voidClaim(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable Long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return ClaimView.of(service.changeStatus(sheetId, user, id, ClaimStatus.VOID));
    }

    @PostMapping("/claims/{id}/approve")
    public ClaimView approve(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable Long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return ClaimView.of(service.approve(sheetId, user, id));
    }

    @PostMapping("/claims/{id}/reject")
    public ClaimView reject(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable Long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid RejectRequest request) {
        return ClaimView.of(service.reject(sheetId, user, id, request.reason()));
    }

    @PostMapping("/claims/{id}/resettle")
    public ClaimView resettle(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable Long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return ClaimView.of(service.resettle(sheetId, user, id));
    }

    @PostMapping("/claims/{id}/defer")
    public ClaimView defer(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable Long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid DeferRequest request) {
        return ClaimView.of(service.defer(sheetId, user, id, request.until()));
    }

    @PostMapping("/claims/{id}/redate")
    public ClaimView redate(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable Long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid RedateRequest request) {
        return ClaimView.of(service.redate(sheetId, user, id, request.date()));
    }

    @PostMapping("/claims/{id}/proof")
    public ClaimView addProof(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable Long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return ClaimView.of(service.addProof(sheetId, user, id));
    }

    @PostMapping("/claims/{id}/reassign")
    public ClaimView reassign(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable Long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid ReassignRequest request) {
        return ClaimView.of(service.reassign(sheetId, user, id, request.personId()));
    }

    @PostMapping("/claims/{id}/split")
    public SplitView split(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable Long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid SplitRequest request) {
        ClaimService.Split split = service.split(sheetId, user, id, request.amountValue());
        return new SplitView(ClaimView.of(split.original()), ClaimView.of(split.split()));
    }
}
package net.officefloor.hq.app.claim;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.FetchType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.OrderColumn;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Objects;

/**
 * A claim by a person on a sheet: an amount (two decimals), a date, a note and a status (DRAFT when
 * added), and a number and who opened it once opened. A negative amount makes it a correction, which
 * names the number of the SETTLED claim of its person that it corrects.
 */
@Entity
@Table(name = "claim")
public class Claim {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    /**
     * Its place in its sheet's list, newest (highest) first: the next of claim_listed_seq, given by the
     * store when added and again when moved to another person.
     */
    @Column(name = "listed", insertable = false)
    private Long listed;

    @Column(name = "amount", nullable = false, precision = 14, scale = 2)
    private BigDecimal amount;

    @Column(name = "claim_date", nullable = false)
    private LocalDate date;

    @Column(name = "note", nullable = false)
    private String note;

    /** The date it is due by, fixed when added: its date plus its person's own terms, else those of their grade then. */
    @Column(name = "due_by", nullable = false, updatable = false)
    private LocalDate dueBy;

    @Enumerated(EnumType.STRING)
    @Column(name = "status", nullable = false)
    private ClaimStatus status = ClaimStatus.DRAFT;

    /**
     * Given when the claim is opened: the sheet-wide number, or <period name>-<n> (X-<n> in no
     * period) while the sheet numbers by period; none while DRAFT, kept when VOID.
     */
    @Column(name = "claim_number")
    private String number;

    /** The period the claim was numbered within (empty: in no period); none unless numbered by period. */
    @Column(name = "number_period")
    private String numberPeriod;

    /** The claim's place in its period's numbering; none unless numbered by period. */
    @Column(name = "number_seq")
    private Integer numberSeq;

    /** The user who opened the claim; none while DRAFT. */
    @Column(name = "opened_by", length = 100)
    private String openedBy;

    /** The due fixed when the claim was settled; none while not settled, or settled with no rate. */
    @Column(name = "settled_due", precision = 14, scale = 2)
    private BigDecimal settledDue;

    /** Bound by its person's last statement, which it counted toward; its due is then {@link #statedDue}. */
    @Column(name = "stated", nullable = false)
    private boolean stated;

    /** The due it had at its person's last statement; none while not stated, or stated with no due. */
    @Column(name = "stated_due", precision = 14, scale = 2)
    private BigDecimal statedDue;

    /** The number of the claim this correction corrects; none unless a correction. */
    @Column(name = "corrects")
    private String corrects;

    /** The number of the claim it was split from; none unless split off one. */
    @Column(name = "split_from")
    private String splitFrom;

    /** How many proofs it has; raised one at a time while not SETTLED or VOID. */
    @Column(name = "proofs", nullable = false)
    private int proofs;

    /** The date it is deferred until; none unless deferred. Deferred only while OPEN and before that date. */
    @Column(name = "deferred_until")
    private LocalDate deferredUntil;

    /** The sheet's today when it was deferred; none unless deferred (or deferred before this was kept). */
    @Column(name = "deferred_on")
    private LocalDate deferredOn;

    /** Whether it was added while the period its due-by falls in was soft-closed. */
    @Column(name = "late_entry", nullable = false)
    private boolean lateEntry;

    /** The user whose open editor locks it for everyone else; none while no editor holds it. */
    @Column(name = "locked_by", length = 100)
    private String lockedBy;
    /** Its status log, oldest first: a line for each status it has had, DRAFT when added. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "claim_log", joinColumns = @JoinColumn(name = "claim_id"))
    @OrderColumn(name = "seq")
    private List<ClaimLogEntry> log = new ArrayList<>();

    /** Its binding log, oldest first: a line each time a statement bound it or it was left unbound again. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "claim_binding", joinColumns = @JoinColumn(name = "claim_id"))
    @OrderColumn(name = "seq")
    private List<ClaimBinding> bindings = new ArrayList<>();

    protected Claim() {}

    public Claim(String sheetId, Long personId, BigDecimal amount, LocalDate date, String note, LocalDate dueBy) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.date = date;
        this.note = note;
        this.dueBy = dueBy;
    }

    public Long getId() { return id; }

    /** A correction: a negative amount. Its due has no floor and no late charge. */
    public boolean isCorrection() { return amount.signum() < 0; }

    public String getCorrects() { return corrects; }

    public void setCorrects(String corrects) { this.corrects = corrects; }

    public String getSplitFrom() { return splitFrom; }

    public void setSplitFrom(String splitFrom) { this.splitFrom = splitFrom; }

    public String getSheetId() { return sheetId; }

    public Long getPersonId() { return personId; }

    public Long getListed() { return listed; }

    /** Move the claim to another person, listed as their newest at the given place in the list. */
    public void moveTo(Long personId, long listed) {
        this.personId = personId;
        this.listed = listed;
    }

    public BigDecimal getAmount() { return amount; }

    public void setAmount(BigDecimal amount) { this.amount = amount; }

    public LocalDate getDate() { return date; }

    public void setDate(LocalDate date) { this.date = date; }

    public String getNote() { return note; }

    /** The date it is due by, fixed when added; it does not move with its date or the terms. */
    public LocalDate getDueBy() { return dueBy; }

    public void setNote(String note) { this.note = note; }

    public ClaimStatus getStatus() { return status; }

    public void setStatus(ClaimStatus status) { this.status = status; }

    public List<ClaimLogEntry> getLog() { return Collections.unmodifiableList(log); }

    /** Log the status it now has, given by the user on the date, with its due at that moment. */
    public void logStatus(String by, LocalDate on, BigDecimal due) {
        log.add(new ClaimLogEntry(status, by, on, due));
    }

    /**
     * The status it had at the end of the date, as its log records it: the last line dated on or before
     * it; null when it had none then (added after it). With no log lines (added before the log was
     * kept) it is taken to have had its status now.
     */
    public ClaimStatus statusAt(LocalDate date) {
        if (log.isEmpty()) return status;
        ClaimStatus at = null;
        for (ClaimLogEntry line : log) if (!line.getDate().isAfter(date)) at = line.getStatus();
        return at;
    }

    /**
     * The due it was settled at, as its status log records it, when SETTLED at the end of the date: the
     * due of its last SETTLED line dated on or before it; with no log lines, its settled due now.
     */
    public BigDecimal settledDueAt(LocalDate date) {
        if (log.isEmpty()) return settledDue;
        BigDecimal due = null;
        for (ClaimLogEntry line : log) {
            if (!line.getDate().isAfter(date) && line.getStatus() == ClaimStatus.SETTLED) due = line.getDue();
        }
        return due;
    }

    /** The date it was last settled, as its status log records it; null when the log has no SETTLED line. */
    public LocalDate settledOn() {
        LocalDate on = null;
        for (ClaimLogEntry line : log) if (line.getStatus() == ClaimStatus.SETTLED) on = line.getDate();
        return on;
    }

    public boolean isLateEntry() { return lateEntry; }
    public void setLateEntry(boolean lateEntry) { this.lateEntry = lateEntry; }

    public String getLockedBy() { return lockedBy; }
    public void setLockedBy(String lockedBy) { this.lockedBy = lockedBy; }
    /** Locked by an open editor of a user other than this one. */
    public boolean isLockedAgainst(String user) { return lockedBy != null && !lockedBy.equals(user.strip()); }
    public String getNumber() { return number; }

    /** Number the claim sheet-wide. */
    public void setNumber(long number) { this.number = String.valueOf(number); }

    /** Number the claim within a period (empty name: in no period): <period name>-<n>, or X-<n>. */
    public void setNumberWithin(String period, int seq) {
        this.numberPeriod = period;
        this.numberSeq = seq;
        this.number = (period.isEmpty() ? "X" : period) + "-" + seq;
    }

    /** The period the claim was numbered within (empty: in no period); null unless numbered by period. */
    public String getNumberPeriod() { return numberPeriod; }

    public Integer getNumberSeq() { return numberSeq; }

    public String getOpenedBy() { return openedBy; }

    public void setOpenedBy(String openedBy) { this.openedBy = openedBy; }

    public BigDecimal getSettledDue() { return settledDue; }

    public void setSettledDue(BigDecimal settledDue) { this.settledDue = settledDue; }

    public boolean isStated() { return stated; }

    public BigDecimal getStatedDue() { return statedDue; }

    /**
     * Whether its due is now bound by its person's last statement: stated and not PENDING. A PENDING
     * claim shows its live due, and is bound again if rejected.
     */
    public boolean isBound() { return stated && status != ClaimStatus.PENDING; }

    /** Bind the claim to a due (null: it has none) on the sheet's today, as its person's statement does. */
    public void state(BigDecimal due, LocalDate on) {
        if (!stated || !Objects.equals(statedDue, due)) bindings.add(new ClaimBinding(on, true, due));
        this.stated = true;
        this.statedDue = due;
    }

    /**
     * The binding it had at the end of the date, as its binding log records it: the last line dated on or
     * before it, null when unbound then. With no log lines it is taken to have had its binding now.
     */
    public ClaimBinding bindingAt(LocalDate date) {
        if (bindings.isEmpty()) return stated ? new ClaimBinding(date, true, statedDue) : null;
        ClaimBinding at = null;
        for (ClaimBinding line : bindings) if (!line.getDate().isAfter(date)) at = line;
        return at != null && at.isStated() ? at : null;
    }

    public int getProofs() { return proofs; }

    /** Raise its proofs count by one. */
    public void addProof() { proofs++; }

    public LocalDate getDeferredUntil() { return deferredUntil; }

    /** Defer it until the date, on the sheet's today. */
    public void deferUntil(LocalDate deferredUntil, LocalDate on) {
        this.deferredUntil = deferredUntil;
        this.deferredOn = on;
    }

    /**
     * Whether it was deferred at the end of the date, with the status it had then: OPEN, deferred on or
     * before the date until a date after it.
     */
    public boolean isDeferredAt(ClaimStatus statusThen, LocalDate date) {
        return statusThen == ClaimStatus.OPEN && deferredUntil != null && date.isBefore(deferredUntil)
                && (deferredOn == null || !deferredOn.isAfter(date));
    }

    /**
     * Whether it is deferred on the date: OPEN, with a deferred-until date after it. A deferred claim counts
     * in no total, is not overdue, cannot be settled and is left unbound by a statement.
     */
    public boolean isDeferredOn(LocalDate today) {
        return status == ClaimStatus.OPEN && deferredUntil != null && today != null && today.isBefore(deferredUntil);
    }

    /** Leave the claim unbound on the sheet's today, its due live again. */
    public void unstate(LocalDate on) {
        if (stated) bindings.add(new ClaimBinding(on, false, null));
        this.stated = false;
        this.statedDue = null;
    }
}
package net.officefloor.hq.app.setting;

import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.util.Map;
import org.springframework.context.annotation.Configuration;
import org.springframework.http.HttpMethod;
import org.springframework.web.method.HandlerMethod;
import org.springframework.web.servlet.HandlerInterceptor;
import org.springframework.web.servlet.HandlerMapping;
import org.springframework.web.servlet.config.annotation.InterceptorRegistry;
import org.springframework.web.servlet.config.annotation.WebMvcConfigurer;

/**
 * Refuses every change a viewer asks of a sheet, before anything is written: any request to a
 * sheet other than a read, unless its handler is {@link OpenToViewer}.
 */
@Configuration
public class ViewerGuard implements WebMvcConfigurer, HandlerInterceptor {

    private final SettingService settings;

    public ViewerGuard(SettingService settings) {
        this.settings = settings;
    }

    @Override
    public void addInterceptors(InterceptorRegistry registry) {
        registry.addInterceptor(this).addPathPatterns("/api/sheets/*/**");
    }

    @Override
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
        if (HttpMethod.GET.matches(request.getMethod()) || HttpMethod.HEAD.matches(request.getMethod())) return true;
        if (!(handler instanceof HandlerMethod method) || method.hasMethodAnnotation(OpenToViewer.class)) return true;
        String user = request.getHeader("X-User");
        String sheetId = sheetId(request);
        if (user == null || user.isBlank() || sheetId == null) return true;
        if (settings.roleOf(sheetId, user) == Role.VIEWER) throw new ViewerRefusedException();
        return true;
    }

    /** The sheet the request is for: its sheetId path variable, or the id of a request to the sheet itself. */
    private static String sheetId(HttpServletRequest request) {
        @SuppressWarnings("unchecked")
        Map<String, String> vars = (Map<String, String>) request.getAttribute(HandlerMapping.URI_TEMPLATE_VARIABLES_ATTRIBUTE);
        if (vars == null) return null;
        return vars.getOrDefault("sheetId", vars.get("id"));
    }
}
package net.officefloor.hq.app.setting;

import java.lang.annotation.ElementType;
import java.lang.annotation.Retention;
import java.lang.annotation.RetentionPolicy;
import java.lang.annotation.Target;

/**
 * A request handler a viewer may call, and that may be called on an archived sheet, although it is
 * not a read: loading a sheet, or a bulk change that itself refuses each selected item for a viewer
 * and on an archived sheet.
 */
@Target(ElementType.METHOD)
@Retention(RetentionPolicy.RUNTIME)
public @interface OpenToViewer {}

